struct OptionProfile { name: &'static str, initial_return: f64, learning: f64, flexibility: f64, reversibility: f64, scalability: f64, modularity: f64, lock_in: f64, carrying_cost: f64, governance: f64, ethics: f64 }
fn score(o: &OptionProfile) -> f64 { 0.10*o.initial_return + 0.17*o.learning + 0.17*o.flexibility + 0.12*o.reversibility + 0.11*o.scalability + 0.13*o.modularity - 0.14*o.lock_in - 0.06*o.carrying_cost + 0.11*o.governance + 0.09*o.ethics }
fn warning(o: &OptionProfile) -> f64 { 0.30*o.lock_in + 0.18*(1.0-o.reversibility) + 0.16*(1.0-o.flexibility) + 0.14*(1.0-o.modularity) + 0.12*(1.0-o.governance) + 0.10*(1.0-o.ethics) }
fn main() { let options = vec![OptionProfile{name:"Pilot Before Scale",initial_return:0.58,learning:0.82,flexibility:0.78,reversibility:0.74,scalability:0.70,modularity:0.64,lock_in:0.32,carrying_cost:0.46,governance:0.70,ethics:0.68}, OptionProfile{name:"Full Commitment Now",initial_return:0.86,learning:0.30,flexibility:0.28,reversibility:0.22,scalability:0.80,modularity:0.24,lock_in:0.82,carrying_cost:0.34,governance:0.48,ethics:0.36}]; for o in options { println!("{} | option value {:.3} | lock-in warning {:.3}", o.name, score(&o), warning(&o)); } }
